import math

def check_divisibility(p, k):
    """Checks if 8*p^k divides 3^(4*p^k) - 1."""
    if p <= 0 or k <= 0 or not is_prime(p):
        return False

    x1 = 8 * (p**k)
    exponent = 4 * (p**k)

    # Calculate (3^exponent - 1) mod x1
    # Use pow(base, exp, mod) for efficient modular exponentiation
    try:
        result = (pow(3, exponent, x1) - 1) % x1
        return result == 0
    except ValueError:
        # This handles cases where x1 might be too large for standard integer types, 
        # although for small p, k it should be fine.
        return False

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Investigate small primes p (excluding 3, as it seems problematic from scratch analysis)
# and small positive integers k.
primes_to_test = [2, 5, 7, 11]
k_range = range(1, 4)

results = {}
for p in primes_to_test:
    results[p] = []
    for k in k_range:
        is_divisible = check_divisibility(p, k)
        results[p].append((k, is_divisible))

print("--- Investigation Results (Divisibility holds if True) ---")
for p, res_list in results.items():
    print(f"Prime p = {p}:")
    for k, found in res_list:
        print(f"  k = {k}: {found}")

# Test p=3 explicitly (as it failed the manual check)
p3_results = {}
for k in k_range:
    is_divisible = check_divisibility(3, k)
    p3_results[k] = is_divisible
print("\nPrime p = 3:")
for k, found in p3_results.items():
    print(f"  k = {k}: {found}")

